"""Conditional Granger Causality Analysis v2: fixed attribute names."""
import json, os, warnings
import numpy as np
import pandas as pd
from statsmodels.tsa.api import VAR

warnings.filterwarnings("ignore")

BASE = "/root/autodl-tmp/distrib_canary_collapse/results"

EXPERIMENTS = {
    "a050_s42":    f"{BASE}/alpha_sweep/a050_s42/all_metrics.json",
    "a050_s43":    f"{BASE}/alpha_sweep/a050_s43/all_metrics.json",
    "a050_s44":    f"{BASE}/alpha_sweep/a050_s44/all_metrics.json",
    "a055_s42":    f"{BASE}/alpha_sweep/a055_s42_fp32/all_metrics.json",
    "a075_s42":    f"{BASE}/alpha_sweep/a075_s42/all_metrics.json",
    "a075_s43":    f"{BASE}/alpha_sweep/a075_s43/all_metrics.json",
    "a075_s44":    f"{BASE}/alpha_sweep/a075_s44/all_metrics.json",
    "pythia410m":  f"{BASE}/generalize/pythia410m_wiki_a100_s42/all_metrics.json",
    "opt1b":       f"{BASE}/generalize/opt1b_wiki_a100_s42/all_metrics.json",
    "pythia1b_c4": f"{BASE}/generalize/pythia1b_c4_a100_s42/all_metrics.json",
    "14b_a050":    f"{BASE}/scale/14b_a050_s42_fp32/all_metrics.json",
    "smollm3_3b":  f"{BASE}/generalize/smollm3_3b_wiki_a100_s42_fp32_v3/all_metrics.json",
}

CANARIES = ["token_entropy", "ece"]
DOWNSTREAMS = ["distinct_1", "distinct_2", "distinct_3", "mauve"]


def load_experiment(path):
    with open(path) as f:
        data = json.load(f)
    return pd.DataFrame(data).sort_values("generation").reset_index(drop=True)


def run_granger(df, caused, causing, extra_vars=None, maxlag=2):
    """
    Run Granger causality test.
    If extra_vars provided, it's a conditional test (VAR includes control variables).
    """
    if extra_vars is None:
        extra_vars = []
    cols = [caused, causing] + extra_vars
    if any(c not in df.columns for c in cols):
        return None
    sub = df[cols].dropna()
    T = len(sub)
    results = {}
    for lag in range(1, maxlag + 1):
        k = len(cols)
        min_obs = lag * k + k + 2
        if T < min_obs:
            results[lag] = {"p": np.nan, "F": np.nan, "df": None, "note": f"T={T}<{min_obs}"}
            continue
        try:
            model = VAR(sub)
            fitted = model.fit(lag)
            test = fitted.test_causality(caused=caused, causing=causing, kind='f')
            results[lag] = {"p": float(test.pvalue), "F": float(test.test_statistic), "df": test.df}
        except Exception as e:
            results[lag] = {"p": np.nan, "F": np.nan, "note": str(e)[:100]}
    return results


def safe_isnan(v):
    try:
        return v != v
    except:
        return True

def fmt_p(p):
    if safe_isnan(p):
        return "    N/A"
    star = "***" if p < 0.001 else " **" if p < 0.01 else "  *" if p < 0.05 else "  ." if p < 0.1 else "   "
    return f"{p:.4f}{star}"

def fmt_f(r, lag=1):
    if r is None or lag not in r or safe_isnan(r[lag]["p"]):
        return "N/A", "N/A"
    return fmt_p(r[lag]["p"]), f"{r[lag]['F']:.2f}"


# ═══════════════════════════════════════════════════════
# Run all tests
# ═══════════════════════════════════════════════════════
all_results = {}

for exp_name, path in EXPERIMENTS.items():
    if not os.path.exists(path):
        print(f"SKIP {exp_name}")
        continue
    df = load_experiment(path)
    T = len(df)
    exp_res = {"T": T, "tests": {}}

    for ds in DOWNSTREAMS:
        if ds not in df.columns:
            continue
        pair = {}
        pair["uncond_ent"]     = run_granger(df, ds, "token_entropy")
        pair["uncond_ece"]     = run_granger(df, ds, "ece")
        pair["cond_ent|ece"]   = run_granger(df, ds, "token_entropy", extra_vars=["ece"])
        pair["cond_ece|ent"]   = run_granger(df, ds, "ece", extra_vars=["token_entropy"])
        pair["joint"]          = run_granger(df, ds, ["token_entropy", "ece"])
        exp_res["tests"][ds] = pair

    all_results[exp_name] = exp_res

# ═══════════════════════════════════════════════════════
# Summary table (lag=1)
# ═══════════════════════════════════════════════════════
print("="*100)
print("CONDITIONAL GRANGER CAUSALITY: lag=1 p-values")
print("="*100)
print(f"{'Experiment':<16} {'Target':<12} {'Unc.TE':>10} {'Unc.ECE':>10} {'TE|ECE':>10} {'ECE|TE':>10} {'Joint':>10}")
print("-"*80)

sig = {k: 0 for k in ["uncond_ent","uncond_ece","cond_ent|ece","cond_ece|ent","joint"]}
n_valid = {k: 0 for k in sig}
total = 0

for exp_name, exp_data in all_results.items():
    for ds, tests in exp_data["tests"].items():
        total += 1
        vals = {}
        for key in sig:
            r = tests.get(key)
            p = r[1]["p"] if r and 1 in r else np.nan
            vals[key] = p
            if not safe_isnan(p):
                n_valid[key] += 1
                if p < 0.05:
                    sig[key] += 1

        row = f"{exp_name:<16} {ds:<12}"
        for key in ["uncond_ent","uncond_ece","cond_ent|ece","cond_ece|ent","joint"]:
            row += f" {fmt_p(vals[key]):>10}"
        print(row)

print(f"\n{'='*80}")
print(f"Significance summary (p<0.05):")
for k in sig:
    print(f"  {k:<20}: {sig[k]}/{n_valid[k]} valid tests ({100*sig[k]/n_valid[k]:.1f}% if valid)")


# ═══════════════════════════════════════════════════════
# Redundancy classification
# ═══════════════════════════════════════════════════════
print(f"\n{'='*80}")
print("REDUNDANCY CLASSIFICATION (lag=1, p<0.05)")
print("="*80)

patterns = {"both_independent": [], "entropy_dominant": [], "ece_dominant": [],
            "redundant_shared": [], "neither_sig": [], "insufficient_data": []}

for exp_name, exp_data in all_results.items():
    for ds, tests in exp_data["tests"].items():
        label = f"{exp_name}/{ds}"

        def getp(key):
            r = tests.get(key)
            return r[1]["p"] if r and 1 in r else np.nan

        p_ue = getp("uncond_ent")
        p_uc = getp("uncond_ece")
        p_ce = getp("cond_ent|ece")
        p_cc = getp("cond_ece|ent")

        if safe_isnan(p_ce) or safe_isnan(p_cc):
            patterns["insufficient_data"].append(label)
            continue

        ent_survives = p_ce < 0.05
        ece_survives = p_cc < 0.05

        if ent_survives and ece_survives:
            patterns["both_independent"].append(label)
        elif ent_survives and not ece_survives:
            patterns["entropy_dominant"].append(label)
        elif not ent_survives and ece_survives:
            patterns["ece_dominant"].append(label)
        elif (not safe_isnan(p_ue) and p_ue < 0.05) or (not safe_isnan(p_uc) and p_uc < 0.05):
            patterns["redundant_shared"].append(label)
        else:
            patterns["neither_sig"].append(label)

for pat, items in patterns.items():
    print(f"\n  {pat} ({len(items)}):")
    for item in items:
        print(f"    - {item}")


# ═══════════════════════════════════════════════════════
# Softer threshold p<0.10
# ═══════════════════════════════════════════════════════
print(f"\n{'='*80}")
print("REDUNDANCY CLASSIFICATION (lag=1, p<0.10)")
print("="*80)

patterns10 = {"both_independent": 0, "entropy_dominant": 0, "ece_dominant": 0,
              "redundant_shared": 0, "neither_sig": 0, "insufficient_data": 0}

for exp_name, exp_data in all_results.items():
    for ds, tests in exp_data["tests"].items():
        def getp(key):
            r = tests.get(key)
            return r[1]["p"] if r and 1 in r else np.nan

        p_ue = getp("uncond_ent")
        p_uc = getp("uncond_ece")
        p_ce = getp("cond_ent|ece")
        p_cc = getp("cond_ece|ent")

        if safe_isnan(p_ce) or safe_isnan(p_cc):
            patterns10["insufficient_data"] += 1
            continue
        ent_survives = p_ce < 0.10
        ece_survives = p_cc < 0.10
        if ent_survives and ece_survives:
            patterns10["both_independent"] += 1
        elif ent_survives and not ece_survives:
            patterns10["entropy_dominant"] += 1
        elif not ent_survives and ece_survives:
            patterns10["ece_dominant"] += 1
        elif (not safe_isnan(p_ue) and p_ue < 0.10) or (not safe_isnan(p_uc) and p_uc < 0.10):
            patterns10["redundant_shared"] += 1
        else:
            patterns10["neither_sig"] += 1

for pat, count in patterns10.items():
    print(f"  {pat:<20}: {count}")


# ═══════════════════════════════════════════════════════
# Canary inter-correlation
# ═══════════════════════════════════════════════════════
print(f"\n{'='*80}")
print("CANARY INTER-CORRELATION (Pearson r: token_entropy vs ECE)")
print("="*80)

for exp_name, path in EXPERIMENTS.items():
    if not os.path.exists(path):
        continue
    df = load_experiment(path)
    r = df["token_entropy"].corr(df["ece"])
    print(f"  {exp_name:<16}: r = {r:+.4f}")


# ═══════════════════════════════════════════════════════
# Partial R² effect sizes
# ═══════════════════════════════════════════════════════
print(f"\n{'='*80}")
print("PARTIAL R^2 FROM VAR(1): incremental variance explained")
print("(How much does adding each canary improve prediction beyond the other?)")
print("="*80)

pr2_data = []

for exp_name, path in EXPERIMENTS.items():
    if not os.path.exists(path):
        continue
    df = load_experiment(path)
    T = len(df)
    if T < 7:
        continue
    print(f"\n  {exp_name} (T={T}):")
    for ds in DOWNSTREAMS:
        if ds not in df.columns:
            continue
        try:
            sub_full = df[[ds, "token_entropy", "ece"]].dropna()
            sub_no_ent = df[[ds, "ece"]].dropna()
            sub_no_ece = df[[ds, "token_entropy"]].dropna()

            ss_full = (VAR(sub_full).fit(1).resid[ds]**2).sum()
            ss_no_ent = (VAR(sub_no_ent).fit(1).resid[ds]**2).sum()
            ss_no_ece = (VAR(sub_no_ece).fit(1).resid[ds]**2).sum()

            pr2_ent = 1.0 - ss_full / ss_no_ent
            pr2_ece = 1.0 - ss_full / ss_no_ece

            winner = "ENT" if pr2_ent > pr2_ece else "ECE" if pr2_ece > pr2_ent else "TIE"
            print(f"    {ds:<12}: pR2(ent)={pr2_ent:.3f}  pR2(ece)={pr2_ece:.3f}  [{winner}]")
            pr2_data.append({"exp": exp_name, "ds": ds, "pr2_ent": pr2_ent, "pr2_ece": pr2_ece})
        except Exception as e:
            print(f"    {ds:<12}: ERROR {str(e)[:60]}")

# Aggregate partial R²
print(f"\n{'='*80}")
print("AGGREGATE PARTIAL R^2")
print("="*80)
if pr2_data:
    pr2_df = pd.DataFrame(pr2_data)
    for ds in DOWNSTREAMS:
        sub = pr2_df[pr2_df["ds"] == ds]
        if len(sub) == 0:
            continue
        ent_wins = (sub["pr2_ent"] > sub["pr2_ece"]).sum()
        ece_wins = (sub["pr2_ece"] > sub["pr2_ent"]).sum()
        print(f"  {ds:<12}: mean pR2(ent)={sub['pr2_ent'].mean():.3f}, mean pR2(ece)={sub['pr2_ece'].mean():.3f} | ENT wins {ent_wins}/{len(sub)}, ECE wins {ece_wins}/{len(sub)}")

    print(f"\n  Overall:")
    ent_wins = (pr2_df["pr2_ent"] > pr2_df["pr2_ece"]).sum()
    ece_wins = (pr2_df["pr2_ece"] > pr2_df["pr2_ent"]).sum()
    print(f"    mean pR2(entropy)={pr2_df['pr2_ent'].mean():.3f}, mean pR2(ECE)={pr2_df['pr2_ece'].mean():.3f}")
    print(f"    Entropy dominates: {ent_wins}/{len(pr2_df)} pairs ({100*ent_wins/len(pr2_df):.1f}%)")
    print(f"    ECE dominates:     {ece_wins}/{len(pr2_df)} pairs ({100*ece_wins/len(pr2_df):.1f}%)")


# Save JSON
output = {"meta": {"analysis": "Conditional Granger v2", "lag": 1}, "summary": {}, "details": {}}
for exp_name, exp_data in all_results.items():
    exp_out = {"T": exp_data["T"], "pairs": {}}
    for ds, tests in exp_data["tests"].items():
        pair_out = {}
        for key, lag_res in tests.items():
            if lag_res is None:
                continue
            pair_out[key] = {}
            for lag, r in lag_res.items():
                pair_out[key][str(lag)] = {"p": r["p"] if not safe_isnan(r["p"]) else None,
                                           "F": r["F"] if not safe_isnan(r.get("F", np.nan)) else None,
                                           "df": list(r["df"]) if r.get("df") else None}
        exp_out["pairs"][ds] = pair_out
    output["details"][exp_name] = exp_out

out_path = "/root/autodl-tmp/distrib_canary_collapse/results/analysis/conditional_granger_v2.json"
with open(out_path, "w") as f:
    json.dump(output, f, indent=2, default=str)
print(f"\nJSON saved to {out_path}")
